#include "stdafx.h"#include "..\MnemoWnd.h"#include "Queue.h"#include "..\Lang.h"#include <string>#include <algorithm>typedef struct : public SPROLOZ  {  COLORREF colorTxt;  int  nTag;  char Tag[256];    //имя точки  char TagData[256];//данные точки в tegs.scn   //  } Queue_TegscnData;//~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~~// Функция отображенияint PaintTegscnData(DefinePaint){  QueueP(Queue_TegscnData);  //  double dvalue=0.;  char svalue[256];  RECT rc(p->mRect);  bool bDontShow=false;  if(  (_stricmp(p->TagData, "H") == 0)     || (_stricmp(p->TagData, "HH") == 0)     || (_stricmp(p->TagData, "L") == 0)     || (_stricmp(p->TagData, "LL") == 0)     || (_stricmp(p->TagData, "min") == 0)     || (_stricmp(p->TagData, "max") == 0)    )    {    if(p->nTag!=-1)      dvalue = ::TegValueD( p->nTag, p->TagData, DBL_MIN );    else dvalue = DBL_MIN;    if (dvalue == DBL_MIN )      if(_stricmp(p->TagData, "min") == 0)          dvalue=0.;      else if (_stricmp(p->TagData, "max") == 0)             dvalue=100.;           else                bDontShow=true;    if(!bDontShow)      {      char *format="%0.2f";      if(abs(dvalue) < 10.)        format="%0.3f";      sprintf_s(svalue, format, dvalue);      }    }  else{      if(p->nTag!=-1)         {         char *ref = (char*)::TegValueS(p->nTag, p->TagData, "");         if(ref)            strcpy_s(svalue, ref);         else bDontShow=true;         }      else bDontShow=true;      }  if(!bDontShow)    ::DrawText( hDC, svalue, -1, &rc, DT_SINGLELINE | DT_TOP | DT_LEFT);  return 1;}void AddTegscnData(DefineTegs){  //  AddQueueEx(Queue_TegscnData);  // Код, посылаемый в АРМ  p->btSendType = QUEUE_NO;  // Определение функции вывода  p->paint = &PaintTegscnData;  p->TagData[0]=0;  //  p->colorTxt= RGB(0,0,0);   STegObj obj[] =    {    { 'R', "rect", &p->mRect },    { 'E', "rc"  , &p->mRect },    { 'S', "data", &p->TagData},    };  ::ParserObjScn( teg, obj, sizeof(obj)/sizeof(STegObj) );  //  strcpy_s(p->Tag, teg[0].value);  p->nTag = ::FindTagEx( p->Tag, id_Sensor );  //в файле DATA\ACY\tegs.scn}